/* Completion-only context. No application pointer is writable through it. */
#ifndef LS_SNAPSHOT_H
#define LS_SNAPSHOT_H

#define LS_SNAPSHOT_SECTION "fexit/snapshot/"
#define LS_SNAPSHOT_PREFIX_LEN 15u
#define LS_SNAPSHOT_ENTRY 1u
#define LS_SNAPSHOT_RETURN 2u
#define LS_SNAPSHOT_CAPTURED 1u

struct ls_snapshot_ctx {
    __UINT64_TYPE__ arg[5];
    __UINT64_TYPE__ no_return;
    __UINT32_TYPE__ phase;
    __UINT32_TYPE__ flags;
    __UINT64_TYPE__ sequence;
    __UINT64_TYPE__ state[4];
};
_Static_assert(sizeof(struct ls_snapshot_ctx) == 96, "snapshot context size");
_Static_assert(__builtin_offsetof(struct ls_snapshot_ctx, state) == 64,
               "snapshot state offset");

/* Host-only identity. Bytecode cannot change it through its private context. */
struct ls_snapshot_id {
    __UINT64_TYPE__ instance;
    __UINT64_TYPE__ epoch;
};
#endif

substrate/ls_target.h.text:
/* Build-resolved attachment record. It lives in .ls.target in the program ELF,
 * hence inside the SHA-256 authenticated by the existing Ed25519 binding. No
 * wire-layout change and no function/type catalog on the deployed host.
 *
 * Version 1 deliberately admits only ELF64 little-endian ET_EXEC x86-64 targets
 * with a 20-byte GNU build ID and a +0/+4 five-NOP entry pad. PIE needs a separate
 * load-bias contract. Return ABI/unwind admission remains the signer's job.
 */
#ifndef LS_TARGET_H
#define LS_TARGET_H
#include <elf.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include "ls_snapshot.h"

#define LS_TARGET_SECTION ".ls.target"
#define LS_TARGET_MAGIC "LSTARG1"
#define LS_TARGET_SNAPSHOT_MAGIC "LSTARG2"
#define LS_TARGET_SET_MAGIC "LSTSET1"
#define LS_TARGET_SET_MAX 12u
struct ls_target {
    char magic[8];
    char build_id[40];             /* full lowercase GNU build ID, no terminator */
    uint64_t entry;                /* function entry, NOT the +4 patch address */
    uint8_t is_exit;
    uint8_t pad_offset;
    uint8_t reserved[6];
};
_Static_assert(sizeof(struct ls_target) == 64, "target record size");
_Static_assert(offsetof(struct ls_target, entry) == 48, "target entry offset");

/* Entry-only multi-program ELF. Each section has exactly one signed target.
 * The loader still loads one selected section per slot. No atomic group arm. */
struct ls_target_set_header {
    char magic[8];
    uint32_t count, reserved;
};
struct ls_target_set_row {
    char section[80];
    struct ls_target target;
};
_Static_assert(sizeof(struct ls_target_set_header) == 16, "target set header");
_Static_assert(sizeof(struct ls_target_set_row) == 144, "target set row");

static int
ls_target_span(size_t len, uint64_t off, uint64_t size)
{
    return off <= len && size <= len - off;
}

/* Parse only bounded bytes, including section names; reject duplicate records.
 * Called after signature verification, but a signed malformed ELF still fails. */
static int
ls_target_parse(const void *elf, size_t len, const char *section,
                const char *build, struct ls_target *out)
{
    const unsigned char *p = elf;
    Elf64_Ehdr e;
    Elf64_Shdr strings, sh;
    unsigned records = 0, programs = 0;
    const unsigned char *record = NULL;
    size_t record_len = 0;
    const char *names[LS_TARGET_SET_MAX];
    if (len < sizeof e) return -1;
    memcpy(&e, p, sizeof e);
    if (memcmp(e.e_ident, ELFMAG, SELFMAG) || e.e_ident[EI_CLASS] != ELFCLASS64 ||
        e.e_ident[EI_DATA] != ELFDATA2LSB || e.e_machine != EM_BPF ||
        e.e_type != ET_REL || e.e_shentsize != sizeof sh ||
        !e.e_shnum || e.e_shstrndx >= e.e_shnum ||
        !ls_target_span(len, e.e_shoff, (uint64_t)e.e_shnum * sizeof sh)) return -1;
    memcpy(&strings, p + e.e_shoff + e.e_shstrndx * sizeof sh, sizeof sh);
    if (strings.sh_type != SHT_STRTAB ||
        !ls_target_span(len, strings.sh_offset, strings.sh_size)) return -1;
    for (unsigned i = 0; i < e.e_shnum; i++) {
        memcpy(&sh, p + e.e_shoff + i * sizeof sh, sizeof sh);
        if (sh.sh_name >= strings.sh_size) return -1;
        const char *name = (const char *)p + strings.sh_offset + sh.sh_name;
        if (!memchr(name, 0, strings.sh_size - sh.sh_name)) return -1;
        if (!strncmp(name, "fentry/", 7) || !strncmp(name, "fexit/", 6)) {
            if (programs == LS_TARGET_SET_MAX ||
                sh.sh_type != SHT_PROGBITS || !(sh.sh_flags & SHF_EXECINSTR) ||
                !sh.sh_size || sh.sh_size % 8 ||
                !ls_target_span(len, sh.sh_offset, sh.sh_size)) return -1;
            for (unsigned j = 0; j < programs; j++)
                if (!strcmp(name, names[j])) return -1;
            names[programs++] = name;
        }
        if (strcmp(name, LS_TARGET_SECTION)) continue;
        if (++records != 1 || sh.sh_type != SHT_PROGBITS ||
            (sh.sh_flags & SHF_EXECINSTR) ||
            !ls_target_span(len, sh.sh_offset, sh.sh_size)) return -1;
        record = p + sh.sh_offset;
        record_len = sh.sh_size;
    }
    if (records != 1 || !programs || !build || strlen(build) != 40)
        return -1;
    if (record_len == sizeof *out) {
        if (programs != 1 || strcmp(names[0], section)) return -1;
        memcpy(out, record, sizeof *out);
    } else {
        struct ls_target_set_header header;
        unsigned seen = 0, selected = 0;
        uint64_t entries[LS_TARGET_SET_MAX];
        if (record_len < sizeof header) return -1;
        memcpy(&header, record, sizeof header);
        if (memcmp(header.magic, LS_TARGET_SET_MAGIC, 8) || header.reserved ||
            header.count != programs || header.count < 2 ||
            record_len != sizeof header +
                header.count * sizeof(struct ls_target_set_row)) return -1;
        for (unsigned i = 0; i < header.count; i++) {
            struct ls_target_set_row row;
            memcpy(&row, record + sizeof header + i * sizeof row, sizeof row);
            const char *nul = memchr(row.section, 0, sizeof row.section);
            if (!nul || strncmp(row.section, "fentry/", 7) ||
                !row.section[7] ||
                memcmp(row.target.magic, LS_TARGET_MAGIC, 8) ||
                memcmp(row.target.build_id, build, 40) ||
                !row.target.entry || row.target.is_exit ||
                (row.target.pad_offset != 0 && row.target.pad_offset != 4))
                return -1;
            for (const char *q = nul; q < row.section + sizeof row.section; q++)
                if (*q) return -1;
            for (unsigned j = 0; j < sizeof row.target.reserved; j++)
                if (row.target.reserved[j]) return -1;
            for (unsigned j = 0; j < i; j++)
                if (entries[j] == row.target.entry) return -1;
            entries[i] = row.target.entry;
            unsigned j = 0;
            while (j < programs && strcmp(row.section, names[j])) j++;
            if (j == programs || (seen & (1u << j))) return -1;
            seen |= 1u << j;
            if (!strcmp(row.section, section)) {
                *out = row.target;
                selected++;
            }
        }
        if (selected != 1 || seen != (1u << programs) - 1) return -1;
    }
    int snapshot = strncmp(section, LS_SNAPSHOT_SECTION,
                           LS_SNAPSHOT_PREFIX_LEN) == 0;
    if (memcmp(out->magic, snapshot ? LS_TARGET_SNAPSHOT_MAGIC :
                                     LS_TARGET_MAGIC, 8) ||
        (snapshot && !section[LS_SNAPSHOT_PREFIX_LEN]) ||
        memcmp(out->build_id, build, 40) || !out->entry ||
        out->is_exit > 1 || out->is_exit != (strncmp(section, "fexit/", 6) == 0) ||
        (out->pad_offset != 0 && out->pad_offset != 4)) return -1;
    for (unsigned i = 0; i < sizeof out->reserved; i++)
        if (out->reserved[i]) return -1;
    return 0;
}

/* Check the signed address against the executing file's executable segments and
 * original pad bytes before any direct dereference of that address is allowed.
 * Read the file, not mutable live text: same-target program replacement can
 * happen while the entry is patched. ls_arm_live separately checks live NOPs. */
static int
ls_target_check_file(const char *path, const struct ls_target *t)
{
    Elf64_Ehdr e;
    Elf64_Phdr ph;
    unsigned char bytes[9];
    const unsigned char expected[9] = {0xf3,0x0f,0x1e,0xfa,0x90,0x90,0x90,0x90,0x90};
    size_t need = t->pad_offset + 5;
    int rc = -1, fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    if (pread(fd, &e, sizeof e, 0) != sizeof e ||
        memcmp(e.e_ident, ELFMAG, SELFMAG) || e.e_ident[EI_CLASS] != ELFCLASS64 ||
        e.e_ident[EI_DATA] != ELFDATA2LSB || e.e_type != ET_EXEC ||
        e.e_machine != EM_X86_64 || e.e_phentsize != sizeof ph ||
        e.e_phoff > INT64_MAX || e.e_phnum > 1024 ||
        (t->pad_offset != 0 && t->pad_offset != 4)) goto out;
    for (unsigned i = 0; i < e.e_phnum; i++) {
        uint64_t off = e.e_phoff + (uint64_t)i * sizeof ph;
        if (off > INT64_MAX || pread(fd, &ph, sizeof ph, (off_t)off) != sizeof ph) goto out;
        if (ph.p_type != PT_LOAD || !(ph.p_flags & PF_X) || t->entry < ph.p_vaddr) continue;
        uint64_t delta = t->entry - ph.p_vaddr;
        if (delta > ph.p_filesz || need > ph.p_filesz - delta ||
            ph.p_offset > INT64_MAX || delta > INT64_MAX - ph.p_offset) continue;
        if (pread(fd, bytes, need, (off_t)(ph.p_offset + delta)) != (ssize_t)need) goto out;
        rc = memcmp(bytes, expected + (t->pad_offset ? 0 : 4), need) ? -1 : 0;
        break;
    }
out:
    close(fd);
    return rc;
}
#endif

substrate/ls_vm.c.text:
/*
 * ls_vm.c --- the embedded eBPF VM. The whole of it.
 *
 * ~120 lines of real code against uBPF's real API. This is what makes the
 * sentence "TMM has its own BPF VM" true; everything else in the scope list is
 * about reaching functions nobody planned for.
 *
 * THE TMM-SIDE CHANGES, in full --- three places, and no more:
 *
 *   1. src/compile/Makefile   link the library
 *          CFLAGS  += -I$(TOPDIR)/.ubpf/vm/inc
 *          LDFLAGS += $(TOPDIR)/.ubpf/build/lib/libubpf.a
 *
 *   2. TMM instance startup, beside the other per-instance init:
 *          ls_vm_init();
 *
 *   3. A call site. One, to start with, at a place already known to fault:
 *
 *          static bool
 *          http_psm_profile_name_lookup(enum errdefs_key key, void *source,
 *                                       errdefs_append append_fn, void *dest)
 *          {
 *              struct http_psm_log_data *log_data = source;
 *              struct http_scb *scb = log_data->scb;
 *              struct connflow *cf = uflow_get_connflow(scb->uf);
 *              struct fw_log_profile_protocol_transfer *ptlp =
 *                  flow_get_listener(cf)->prot_transfer_log_profile;
 *
 *     [SUPERSEDED --- illustrates the RETIRED typed-ctx model. Today the trampoline hands
 *      every program the generic register ctx and a CO-RE program reads fields by relocation;
 *      no per-hook ctx type is built in the host. Kept as the design record of why.]
 *     +        struct ls_ctx_http_psm c = {                  // per-core scratch
 *     +            .ptlp      = (uint64_t)(uintptr_t)ptlp,
 *     +            .ptlp_name = ptlp ? (uint64_t)(uintptr_t)ptlp->name : 0,
 *     +            .name_len  = (ptlp && ptlp->name) ? (uint32_t)strlen(ptlp->name) : 0,
 *     +        };
 *     +        if (ls_vm_call(ls_ptlog_slot, &c, sizeof c) == LS_SAFE_RETURN)
 *     +            return false;                             // the declared safe value
 *
 *     and at init, passing BOTH identities (O14):
 *     +        ls_ptlog_slot = ls_vm_arm(blob, sizeof blob,
 *     +                                  "fentry/http_psm_profile_name_lookup",
 *     +                                  "shield", LS_MODE_ENFORCE);
 *
 *              const char *str = ptlp->name;
 *              return append_fn(str, strlen(str), dest);
 *          }
 *
 * That third block is the entire per-hook cost, and it is the DESIGNED-IN form:
 * a deliberate call site in source F5 owns. The trampoline and pad-rewriting
 * work exists to get this same effect at a function nobody edited --- a bigger
 * claim, and not this one.
 *
 * Note what the call site does NOT do: it does not consult the mode. The program
 * always selects the outcome its predicate implies and the host decides whether
 * to apply it, because gating mode inside the program would make a monitor-mode
 * hit indistinguishable from a miss.
 *
 * Status: candidate artifact. Compiles against the vendored uBPF headers.
 * Nothing in this repo instantiates it inside TMM.
 */

#include "ls_vm.h"
#include "ls_vm_config.h"
#include "ls_tp.h"          /* ls_tp_emit_shield --- the enforcement-evidence event */
#include "vm_stack_policy.h"
#include "ls_map.h"
#include "ls_map_glue.h"
#include "ls_core_relo.h"
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

#include <elf.h>
#include <stdio.h>
#include <stdlib.h>   /* free() for uBPF's error strings */
#include <string.h>

#include "ubpf.h"

/* 12, matching the LS_TRAMP expansions in trampoline_x86_64.S. The two are compared
 * at arm time against the count that file publishes --- see ls_arm.c --- because a
 * C-side constant larger than the real table indexes past .rodata and arms a wild
 * address. Raised from 8 on 2026-08-18 for the ssl__err tracepoint plus headroom. */
#define LS_MAX_SLOTS 12

/*
 * Per-instance program stack, allocated once.
 *
 * ubpf_exec() declares `uint64_t stack[UBPF_EBPF_STACK_SIZE/8]` --- 4 KB --- as a
 * local, so every invocation pushes and touches a 4 KB frame at whatever depth
 * TMM's call graph happens to be at. That is the same hazard finding O7 raised
 * against the JIT prologue, present on the interpreter path as well, and it is
 * paid per call rather than once.
 *
 * ubpf_exec_ex() takes the stack from the caller, so we allocate it once per TMM
 * instance and hand the same one to every invocation. Safe here for the reason
 * the rest of this file is lock-free: one VM per instance, run-to-completion, so
 * two invocations never overlap on a core. It would NOT be safe if a hook could
 * be re-entered --- a shield that somehow triggered the hooked path again would
 * corrupt its own stack, which is why re-entrancy is on the trampoline's
 * requirement list (scope item 1) rather than assumed away.
 */
/* Defined below ls_vm_call, which it uses; declared here because ls_vm_arm
 * invokes it. */
static void ls_vm_selftest(int slot, unsigned level);

static uint8_t *g_prog_stack;
#define LS_PROG_STACK_SIZE 4096

/* Per TMM instance. Not shared, not locked --- see the header. `static` because
 * each TMM instance is its own process. */
static struct ls_slot g_slots[LS_MAX_SLOTS];
static bool           g_ready;

/* What PREVAIL was told, and therefore what uBPF must allocate. Passed to uBPF
 * as the calculator cookie so the two agree by construction rather than by two
 * defaults coincidentally matching (item 6a; see vm_stack_policy.h). */
static const struct vm_stack_policy g_policy = { .proven_frame = 256, .max_depth = 8 };

static struct ls_vm_config g_cfg;

/* Where the program came from, for the arm-time log. Knowing WHICH shield a pod
 * is running has already been a question once; it should never be a guess. */
static char g_origin[160];

/*
 * Read the timestamp counter. Used only when LS_VM_TIMING or LS_VM_BENCH is on,
 * so the shipped path is untouched by default.
 *
 * This is a CYCLE COUNT, not a duration, and the two are not interchangeable on
 * a machine that scales frequency. It is the right primitive for comparing two
 * paths on one box; it is the wrong primitive for quoting nanoseconds. The
 * aarch64 counter is worse still --- 10-40ns granularity against a budget of
 * tens of ns (finding O6) --- which is why any arm64 number from this needs its
 * own caveat rather than the same one.
 */
static inline uint64_t
ls_cycles(void)
{
#if defined(__x86_64__)
    uint32_t lo, hi;
    __asm__ __volatile__("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
#elif defined(__aarch64__)
    uint64_t v;
    __asm__ __volatile__("mrs %0, cntvct_el0" : "=r"(v));
    return v;
#else
    return 0;
#endif
}

/* Read a program from a file instead of the compiled-in blob. This is what turns
 * "change the shield" from a rebuild into a restart. Bounded: a program that
 * does not fit the cap is refused rather than truncated, because a truncated
 * ELF that happens to parse is worse than no program. */
#define LS_MAX_PROG 262144

/* Allocated for the file's actual size, at init, and freed once the program is
 * loaded into the VM. A static buffer here is permanently-resident .bss in every
 * TMM instance --- one per core --- holding a copy of something uBPF has already
 * copied. Measured: the static version cost 256 KB per instance for nothing. */
static unsigned char *g_filebuf;

static size_t
ls_read_program(const char *path)
{
    FILE *f = fopen(path, "rb");
    if (f == NULL)
        return 0;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return 0; }
    long sz = ftell(f);
    rewind(f);
    if (sz <= 0 || sz > LS_MAX_PROG) {
        fprintf(stderr, "ls_vm: %s is %ld bytes; limit is %d --- refusing rather "
                        "than truncating\n", path, sz, LS_MAX_PROG);
        fclose(f);
        return 0;
    }
    free(g_filebuf);
    g_filebuf = malloc((size_t)sz);
    if (g_filebuf == NULL) { fclose(f); return 0; }
    size_t n = fread(g_filebuf, 1, (size_t)sz, f);
    fclose(f);
    return (n == (size_t)sz) ? n : 0;
}

/* Adapter, not a cast. vm_stack_policy.h deliberately does not include uBPF's
 * headers --- it must stay checkable on its own --- so its calculator takes
 * `const void *` where uBPF's typedef takes `const struct ubpf_vm *`. Those are
 * DIFFERENT function pointer types, and calling through a converted incompatible
 * function pointer is undefined behaviour, not a style question. One forwarding
 * function costs nothing and keeps both sides honest. */
static int
ls_stack_usage(const struct ubpf_vm *vm, uint16_t pc, void *cookie)
{
    return vm_stack_usage((const void *)vm, pc, cookie);
}


/*
 * Does `function` live in `section` within this object? (Finding O14.)
 *
 * PREVAIL is told a SECTION and proves the program there. uBPF is told a FUNCTION
 * SYMBOL and runs that. Nothing in either tool relates the two, so an object with
 * more than one function can be verified as one program and executed as another.
 * This closes that by reading the object's own symbol table.
 *
 * Written defensively on purpose: `elf_len` is attacker-influenced in the real
 * loader path, so every offset is bounds-checked against it before use. Returns
 * 1 only when the relationship is positively established --- unknown is a refusal,
 * not a pass.
 */
static int
ls_symbol_is_in_section(const void *elf, size_t elf_len,
                        const char *section, const char *function)
{
    const unsigned char *base = (const unsigned char *)elf;

    if (elf == NULL || section == NULL || function == NULL)
        return 0;
    if (elf_len < sizeof(Elf64_Ehdr))
        return 0;

    Elf64_Ehdr eh;
    memcpy(&eh, base, sizeof eh);
    if (memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0 || eh.e_ident[EI_CLASS] != ELFCLASS64)
        return 0;
    if (eh.e_shentsize != sizeof(Elf64_Shdr) || eh.e_shnum == 0)
        return 0;
    /* section header table must lie wholly inside the object */
    if (eh.e_shoff > elf_len ||
        (size_t)eh.e_shnum * sizeof(Elf64_Shdr) > elf_len - (size_t)eh.e_shoff)
        return 0;
    if (eh.e_shstrndx >= eh.e_shnum)
        return 0;

    const Elf64_Shdr *sh = (const Elf64_Shdr *)(const void *)(base + eh.e_shoff);

    /* section-name string table */
    const Elf64_Shdr *shstr = &sh[eh.e_shstrndx];
    if (shstr->sh_offset > elf_len || shstr->sh_size > elf_len - shstr->sh_offset)
        return 0;
    const char *shstrtab = (const char *)(base + shstr->sh_offset);

    /* find the symbol table and its string table */
    const Elf64_Shdr *symtab = NULL;
    for (unsigned i = 0; i < eh.e_shnum; i++) {
        if (sh[i].sh_type == SHT_SYMTAB) { symtab = &sh[i]; break; }
    }
    if (symtab == NULL || symtab->sh_entsize != sizeof(Elf64_Sym))
        return 0;
    if (symtab->sh_offset > elf_len || symtab->sh_size > elf_len - symtab->sh_offset)
        return 0;
    if (symtab->sh_link >= eh.e_shnum)
        return 0;

    const Elf64_Shdr *strh = &sh[symtab->sh_link];
    if (strh->sh_offset > elf_len || strh->sh_size > elf_len - strh->sh_offset)
        return 0;
    const char *strtab = (const char *)(base + strh->sh_offset);

    const Elf64_Sym *sym = (const Elf64_Sym *)(const void *)(base + symtab->sh_offset);
    size_t nsyms = (size_t)(symtab->sh_size / sizeof(Elf64_Sym));

    for (size_t i = 0; i < nsyms; i++) {
        if (sym[i].st_name >= strh->sh_size)
            continue;                       /* name would run off the string table */
        if (strcmp(strtab + sym[i].st_name, function) != 0)
            continue;
        if (ELF64_ST_TYPE(sym[i].st_info) != STT_FUNC)
            continue;                       /* a data symbol of the same name is not it */
        if (sym[i].st_shndx >= eh.e_shnum)
            return 0;                       /* SHN_UNDEF / ABS: not defined here */

        const Elf64_Shdr *owner = &sh[sym[i].st_shndx];
        if (owner->sh_name >= shstr->sh_size)
            return 0;
        return strcmp(shstrtab + owner->sh_name, section) == 0;
    }
    return 0;                               /* no such function: refuse */
}

/* The single STT_FUNC symbol defined in `section` --- the program's entry, taken FROM the
 * object we verified rather than assumed to be a fixed name. Same bounds discipline as
 * ls_symbol_is_in_section. Returns the name length (copied into out), or 0 if none. */
size_t
ls_function_in_section(const void *elf, size_t elf_len, const char *section,
                       char *out, size_t outlen)
{
    const unsigned char *base = elf;
    if (elf == NULL || section == NULL || out == NULL || outlen == 0) return 0;
    if (elf_len < sizeof(Elf64_Ehdr)) return 0;
    Elf64_Ehdr eh; memcpy(&eh, base, sizeof eh);
    if (eh.e_shentsize != sizeof(Elf64_Shdr) || eh.e_shnum == 0) return 0;
    if (eh.e_shoff > elf_len || (size_t)eh.e_shnum * sizeof(Elf64_Shdr) > elf_len - eh.e_shoff) return 0;
    const Elf64_Shdr *sh = (const Elf64_Shdr *)(const void *)(base + eh.e_shoff);
    if (eh.e_shstrndx >= eh.e_shnum) return 0;
    const Elf64_Shdr *shstr = &sh[eh.e_shstrndx];
    if (shstr->sh_offset > elf_len || shstr->sh_size > elf_len - shstr->sh_offset) return 0;
    const char *shstrtab = (const char *)(base + shstr->sh_offset);
    const Elf64_Shdr *symtab = NULL;
    for (unsigned i = 0; i < eh.e_shnum; i++)
        if (sh[i].sh_type == SHT_SYMTAB) { symtab = &sh[i]; break; }
    if (symtab == NULL || symtab->sh_entsize != sizeof(Elf64_Sym)) return 0;
    if (symtab->sh_offset > elf_len || symtab->sh_size > elf_len - symtab->sh_offset) return 0;
    if (symtab->sh_link >= eh.e_shnum) return 0;
    const Elf64_Shdr *strh = &sh[symtab->sh_link];
    if (strh->sh_offset > elf_len || strh->sh_size > elf_len - strh->sh_offset) return 0;
    const char *strtab = (const char *)(base + strh->sh_offset);
    const Elf64_Sym *sym = (const Elf64_Sym *)(const void *)(base + symtab->sh_offset);
    size_t nsyms = (size_t)(symtab->sh_size / sizeof(Elf64_Sym));
    for (size_t i = 0; i < nsyms; i++) {
        if (ELF64_ST_TYPE(sym[i].st_info) != STT_FUNC) continue;
        if (sym[i].st_shndx >= eh.e_shnum || sym[i].st_name >= strh->sh_size) continue;
        const Elf64_Shdr *owner = &sh[sym[i].st_shndx];
        if (owner->sh_name >= shstr->sh_size) continue;
        if (strcmp(shstrtab + owner->sh_name, section) != 0) continue;
        const char *nm = strtab + sym[i].st_name;
        size_t n = strlen(nm);
        if (n == 0 || n >= outlen) return 0;
        memcpy(out, nm, n + 1);
        return n;
    }
    return 0;
}

bool
ls_vm_init(void)
{
    memset(g_slots, 0, sizeof g_slots);
    ls_vm_config_load(&g_cfg);
    if (g_prog_stack == NULL) {
        g_prog_stack = calloc(1, LS_PROG_STACK_SIZE);
        if (g_prog_stack == NULL)
            return false;
    }
    if (!g_cfg.enable) {
        /* A shield that misbehaves must be switchable off without reverting the
         * integration and without a rebuild. */
        fprintf(stderr, "ls_vm: disabled by LS_SHIELD_ENABLE=0\n");
        return false;
    }
    g_ready = true;
    if (g_cfg.verbose)
        fprintf(stderr, "ls_vm: init  build=%s %s  jit=%d fuel=%u timing=%d\n",
                __DATE__, __TIME__, (int)g_cfg.jit, g_cfg.fuel, (int)g_cfg.timing);
    return true;
}

bool
ls_vm_stats(int slot, struct ls_stats *out)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || out == NULL)
        return false;
    const struct ls_slot *s = &g_slots[slot];
    out->armed = s->armed;
    out->is_exit = s->is_exit;
    out->mode = (int)s->mode;
    out->fired = s->fired;
    out->safe_returns = s->safe_returns;
    /* Counters are per SLOT and survive a program swap. That residue was read as
     * a result twice on 2026-08-17 --- a safe_returns=246 left by one program was
     * taken as evidence about the next. `gen` increments on every reload, so a
     * reader can tell whether the counts belong to the program it just loaded. */
    out->gen = s->gen;
    out->errors = s->errors;
    out->cycles = s->cycles;
    out->cycles_max = s->cycles_max;
    out->cycles_min = s->cycles_min;
    out->snapshot_entry_errors = s->snapshot_entry_errors;
    out->snapshot_return_errors = s->snapshot_return_errors;
    return true;
}

uint64_t
ls_vm_safe_value(int slot)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return 0;
    return g_slots[slot].safe_value;
}

unsigned
ls_vm_samples(int slot, struct ls_ctx_sample *out, unsigned max)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || out == NULL)
        return 0;
    struct ls_slot *s = &g_slots[slot];
    unsigned have = s->sample_next < LS_CTX_SAMPLES ? (unsigned)s->sample_next
                                                    : LS_CTX_SAMPLES;
    if (have > max)
        have = max;
    for (unsigned i = 0; i < have; i++)
        out[i] = s->samples[i];
    return have;
}

/*
 * Load a program, benchmark it, throw it away --- WITHOUT arming it onto a hook.
 *
 * Move-3 instrument. Calibrating the budget pass needs the measured cost of many
 * programs of varying length and opcode mix. Doing that through LS_SHIELD_PATH
 * costs a pod restart per data point; doing it here costs a message. That is the
 * difference between fitting a model and sampling twice and guessing.
 *
 * Runs on the loader thread, off the data path, and never touches a live slot.
 */
int
ls_vm_bench_program(const void *elf, size_t elf_len,
                    const char *section, const char *function,
                    uint32_t iters,
                    uint64_t *min_out, uint64_t *mean_out, uint64_t *max_out,
                    int *jitted_out)
{
    char *err = NULL;
    struct ubpf_vm *vm = NULL;
    uint8_t *stack = NULL;
    unsigned char ctx[LS_TRACING_CTX_SIZE];
    uint64_t ret = 0, best = ~0ull, worst = 0, total = 0;
    int rc = -1;

    if (elf == NULL || iters == 0)
        return -1;
    if (!ls_symbol_is_in_section(elf, elf_len, section, function))
        return -1;                          /* same O14 gate as the real path */

    vm = ubpf_create();
    if (vm == NULL)
        return -1;
    if (ubpf_register_stack_usage_calculator(vm, ls_stack_usage, (void *)&g_policy) != 0)
        goto out;
    /* Maps, before the load --- the bench path needs it for the same reason the
     * arm path does: a program with maps must measure with its maps working, or
     * the number describes a program that fell through every lookup. */
    if (ls_map_glue_install(vm) != 0)
        goto out;
    if (ubpf_load_elf_ex(vm, elf, elf_len, function, &err) < 0)
        goto out;
    if (g_ls_config.load_error)
        goto out;

    /* Its own stack: the shared one belongs to the data path, and this runs on
     * the loader thread. */
    stack = calloc(1, LS_PROG_STACK_SIZE);
    if (stack == NULL)
        goto out;

    /*
     * MEASURE THE PATH AN ARMED HOOK ACTUALLY TAKES.
     *
     * This loop called ubpf_exec_ex --- the INTERPRETER --- while ls_vm_call prefers jit_fn
     * whenever it is non-NULL, and this build runs with jit=1. So the figure it produced
     * described an execution path no armed hook uses. It was not wrong by a little: an
     * earlier off-TMM measurement in this repo put the interpreter at 48 ns against the JIT's
     * 10 ns, and the whole reason this op exists is to answer "what does a hook cost per
     * call". Reporting the interpreter under that question invites exactly one misreading and
     * it is the pessimistic one.
     *
     * So: compile when the configuration says to, call through the same ubpf_jit_ex_fn cast
     * ls_vm_call uses, with the same stack argument, and report WHICH path was measured so
     * the number cannot be read as the other one.
     *
     * EXTENDED mode, matching ls_vm_arm. Basic mode's prologue allocates its own stack ---
     * ubpf.h: "automatically allocates a stack" --- which is the unprobed 4 KB frame finding
     * O7 is about, and it would also make this measure a different prologue than the live one.
     *
     * A JIT FAILURE FALLS BACK rather than aborting: an unbenchmarkable program is less useful
     * than an interpreter figure that says so. The caller is told which it got.
     */
    ubpf_jit_ex_fn jf = NULL;

    if (g_cfg.jit) {
        char *jerr = NULL;
        ubpf_set_jit_code_size(vm, LS_JIT_CODE_MAX);
        jf = ubpf_compile_ex(vm, &jerr, ExtendedJitMode);
        if (jf == NULL) {
            fprintf(stderr, "ls_vm: bench: JIT failed (%s) --- measuring the interpreter "
                            "instead; the number is NOT the armed-hook path\n",
                    jerr ? jerr : "?");
        }
        free(jerr);
    }
    if (jitted_out)
        *jitted_out = (jf != NULL);

    memset(ctx, 0, sizeof ctx);
    /* Warm the caches and, on the JIT path, fault in the generated code. Measuring the first
     * call would measure the page fault. */
    for (uint32_t i = 0; i < 100 && i < iters; i++) {
        if (jf != NULL)
            (void)jf(ctx, sizeof ctx, stack, LS_PROG_STACK_SIZE);
        else
            (void)ubpf_exec_ex(vm, ctx, sizeof ctx, &ret, stack, LS_PROG_STACK_SIZE);
    }

    for (uint32_t i = 0; i < iters; i++) {
        uint64_t t0 = ls_cycles();
        if (jf != NULL) {
            /* No error channel, exactly as on the data path: ls_vm_call cannot tell a faulting
             * compiled program from a returning one either. That asymmetry with the
             * interpreter branch below is a real property of the JIT, not an omission here. */
            (void)jf(ctx, sizeof ctx, stack, LS_PROG_STACK_SIZE);
        } else if (ubpf_exec_ex(vm, ctx, sizeof ctx, &ret, stack, LS_PROG_STACK_SIZE) != 0) {
            goto out;
        }
        uint64_t d = ls_cycles() - t0;
        total += d;
        if (d < best)  best = d;
        if (d > worst) worst = d;
    }
    if (min_out)  *min_out  = best;
    if (mean_out) *mean_out = total / iters;
    if (max_out)  *max_out  = worst;
    rc = 0;
out:
    free(err);
    free(stack);
    if (vm) ubpf_destroy(vm);
    return rc;
}

void
ls_vm_report(void)
{
    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        const struct ls_slot *s = &g_slots[i];
        if (!s->armed)
            continue;
        fprintf(stderr,
                "ls_vm: slot=%d mode=%d fired=%llu safe_returns=%llu errors=%llu"
                " cycles_total=%llu cycles_mean=%llu cycles_max=%llu\n",
                i, (int)s->mode,
                (unsigned long long)s->fired, (unsigned long long)s->safe_returns,
                (unsigned long long)s->errors, (unsigned long long)s->cycles,
                (unsigned long long)(s->fired ? s->cycles / s->fired : 0),
                (unsigned long long)s->cycles_max);
    }
}

/*
 * Run the program N times over a fixed ctx and report cycle statistics.
 *
 * This exists because the alternative --- waiting for live traffic to reach one
 * specific vulnerable function --- requires a listener configured with a
 * protocol-transfer log profile, which is a whole config exercise standing
 * between us and a number. The benchmark answers "what does one invocation
 * cost" directly.
 *
 * What it measures: ubpf_exec plus this function's own loop overhead, on a warm
 * cache, with no contention. That is the FLOOR. A real invocation adds the ctx
 * build, a cold-ish cache, and whatever the poll loop is doing. Report it as a
 * floor or not at all.
 */
static void
ls_vm_bench(int slot, uint32_t iters)
{
    struct ls_slot *s = &g_slots[slot];
    unsigned char ctx[LS_TRACING_CTX_SIZE];
    uint64_t ret = 0, best = ~0ull, worst = 0, total = 0;

    if (!s->armed || iters == 0)
        return;
    memset(ctx, 0, sizeof ctx);        /* the NULL case: the shield's hot branch */

    ubpf_jit_ex_fn jf = (ubpf_jit_ex_fn)s->jit_fn;

    for (uint32_t i = 0; i < 100 && i < iters; i++)   /* warm */
        if (jf) (void)jf(ctx, sizeof ctx, g_prog_stack, LS_PROG_STACK_SIZE);
        else    (void)ubpf_exec_ex(s->vm, ctx, sizeof ctx, &ret, g_prog_stack, LS_PROG_STACK_SIZE);

    for (uint32_t i = 0; i < iters; i++) {
        uint64_t t0 = ls_cycles();
        int rc = 0;
        if (jf) ret = jf(ctx, sizeof ctx, g_prog_stack, LS_PROG_STACK_SIZE);
        else    rc  = ubpf_exec_ex(s->vm, ctx, sizeof ctx, &ret, g_prog_stack, LS_PROG_STACK_SIZE);
        uint64_t d = ls_cycles() - t0;
        if (rc != 0) { fprintf(stderr, "ls_vm: bench exec fault at %u\n", i); return; }
        total += d;
        if (d < best)  best = d;
        if (d > worst) worst = d;
    }
    fprintf(stderr,
            "ls_vm: bench slot=%d path=%s iters=%u min=%llu mean=%llu max=%llu cycles"
            "  (floor: warm cache, no contention, ubpf_exec only --- NOT a"
            " per-packet cost)\n",
            slot, jf ? "JIT" : "interp", iters, (unsigned long long)best,
            (unsigned long long)(total / iters), (unsigned long long)worst);
}

/* ---- CO-RE target BTF: THIS build's type info, embedded in the binary ----
 * The kernel embeds BTF in vmlinux as a `.BTF` section (pahole at build; see
 * evidence/cache/kernel-btf.html) and re-exposes it via /sys/kernel/btf/vmlinux
 * only because userspace cannot read kernel memory. TMM is a userspace process,
 * so its equivalent is to read its OWN `.BTF` section from /proc/self/exe --- the
 * same model minus the sysfs indirection. Packaging embeds `.BTF` into the binary
 * (pahole + objcopy --add-section); this reads it back. The BTF therefore cannot
 * mismatch the binary: it IS the binary's own section. */

/* One fact, one whitelist entry: the parsed target BTF and its load state
 * (0 unset, 1 ok, -1 failed). Folded into a struct rather than two globals so the
 * mutable-state manifest gains one name, not two --- see ls_audit's lesson. */
static struct { struct btf b; int state; } g_ls_btf;

/* Load and parse the binary's own `.BTF` once, lazily, on the TMM thread (malloc
 * is legal here; reached only via ls_prep_run_pending). The mmap outlives the
 * parse deliberately --- ls_core_btf_open does not copy the blob. */
static const struct btf *
ls_vm_target_btf(void)
{
    if (g_ls_btf.state == 0) {
        g_ls_btf.state = -1;                          /* pessimistic until proven */
        int fd = open("/proc/self/exe", O_RDONLY);
        if (fd >= 0) {
            off_t sz = lseek(fd, 0, SEEK_END);
            void *mem = (sz > 0 && sz < (off_t)0x80000000)
                          ? mmap(NULL, (size_t)sz, PROT_READ, MAP_PRIVATE, fd, 0)
                          : MAP_FAILED;
            close(fd);
            if (mem != MAP_FAILED) {
                const uint8_t *btf = 0; uint32_t btf_sz = 0;
                if (ls_core_btf_find_in_elf(mem, (uint32_t)sz, &btf, &btf_sz) == 0 &&
                    ls_core_btf_open(&g_ls_btf.b, btf, btf_sz) == 0)
                    g_ls_btf.state = 1;
            }
        }
        if (g_ls_btf.state != 1)
            fprintf(stderr, "ls_vm: no usable `.BTF` section in /proc/self/exe --- programs "
                            "cannot be relocated and will be refused\n");
    }
    return g_ls_btf.state == 1 ? &g_ls_btf.b : NULL;
}

int
ls_vm_arm(const void *elf, size_t elf_len,
          const char *section, const char *function, enum ls_mode m)
{
    int slot = -1;
    char *err = NULL;

    if (!g_ready || elf == NULL || section == NULL || function == NULL)
        return -1;

    /* O14: the verifier proved the program in `section`; uBPF is about to run the
     * one named `function`. Refuse unless they are the same program. */
    if (!ls_symbol_is_in_section(elf, elf_len, section, function)) {
        fprintf(stderr, "ls_vm: refusing --- '%s' does not live in section '%s'; "
                        "the verified program and the loaded one may differ\n",
                function, section);
        return -1;
    }

    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        if (!g_slots[i].armed) { slot = i; break; }
    }
    if (slot < 0)
        return -1;

    /* The hook KIND rides on the verified section: a program compiled for
     * fexit/<fn> is armed at the function's RETURN (ls_fexit_table), one for
     * fentry/<hook> at its ENTRY. Recorded now, read at arm --- see ls_arm_live. */
    g_slots[slot].is_exit = (strncmp(section, "fexit/", 6) == 0);
    g_slots[slot].is_snapshot =
        strncmp(section, LS_SNAPSHOT_SECTION, LS_SNAPSHOT_PREFIX_LEN) == 0;
    g_slots[slot].snapshot_id.instance = g_ls_config.loading;
    g_slots[slot].snapshot_id.epoch = 1;
    if (g_slots[slot].is_snapshot &&
        (!g_ls_config.loading || m > LS_MODE_MONITOR))
        return -1;

    /* The safe-return value for THIS slot (item 7, v1: one configured value via
     * env, not yet the per-return-type policy table). Read here, off the data
     * path, and delivered by ls_tramp_dispatch. Default 0 is correct for a
     * pointer/BOOL hook and WRONG for an err_t one --- dtls_tx wants ERR_BUF(2),
     * set with LS_SHIELD_SAFE_VALUE=2 at arm. */
    {
        const char *sv = getenv("LS_SHIELD_SAFE_VALUE");
        g_slots[slot].safe_value = (sv != NULL && *sv != '\0')
                                 ? (uint64_t)strtoull(sv, NULL, 0) : 0;
    }

    struct ubpf_vm *vm = ubpf_create();
    if (vm == NULL)
        return -1;

    /* Before load: make the runtime allocate the frame the proof assumed.
     * Registering this is not optional --- without it uBPF falls back to 256
     * regardless of what the program was verified against, and a calculator
     * that returns 0 gets a ZERO-byte frame (finding O13). */
    if (ubpf_register_stack_usage_calculator(vm, ls_stack_usage, (void *)&g_policy) != 0)
        goto fail;

    /* Maps. MUST precede ubpf_load_elf_ex: the relocation callback is consulted
     * while uBPF walks the maps section, and a VM without it hands every helper
     * map=0 --- a program that loads, verifies, runs, and whose maps are silently
     * always empty. That is exactly the state this build was in. */
    if (ls_map_glue_install(vm) != 0)
        goto fail;

    /* CO-RE RELOCATION --- before verify+JIT. A portable program names TMM fields
     * by struct+field name and carries .BTF.ext records; here each is resolved to
     * THIS build's byte offset (from the baked BTF) and the instruction immediate
     * is patched, so one bytecode runs on any build with no baked offset and no
     * rebuild. `elf` is the caller's private, mutable prep buffer, so patching in
     * place is sound. FAIL-DARK: a program we cannot fully relocate is refused,
     * never run against a stale offset; a program with no .BTF.ext (nothing to
     * relocate) proceeds. Reached on the TMM thread, where malloc is legal. */
    {
        /* ASK WHETHER RELOCATION IS NEEDED BEFORE DEMANDING THE TYPE INFORMATION.
         *
         * This block used to call ls_vm_target_btf() first and refuse outright on
         * NULL. That is correct only while the binary carries its own `.BTF`, and
         * it is the single line standing between here and removing that section
         * (02-RESEARCH-PARAMETERS.md P9): once offsets are resolved at sign time
         * the shipped program has `.BTF`/`.BTF.ext` STRIPPED and needs no target
         * BTF at all --- but the old order refused it for lacking something it does
         * not use. The check further down already tolerated -LS_RELO_ENOBTF, so
         * the tolerance existed and was unreachable, guarded by a refusal above it.
         *
         * The three cases are now distinguished, and the middle one is the point:
         *   needs relocation + BTF present -> relocate, as before
         *   needs NO relocation            -> proceed; the target BTF is never read
         *   needs relocation + no BTF      -> REFUSE, naming the actual problem
         *
         * FAIL-DARK ON "CANNOT TELL". A malformed object gives -1 from the probe,
         * and that is treated as "needs relocation" --- never as "nothing to do".
         * Guessing the latter would run a program against unresolved placeholder
         * offsets (0, 1, 2 for a stub struct), reading whatever sits at the front
         * of a real TMM structure. Silently, and with PREVAIL's blessing, because
         * the proof was taken against the placeholder. */
        int needs = ls_core_elf_has_relos((const uint8_t *)elf, (uint32_t)elf_len);
        const struct btf *tb = (needs != 0) ? ls_vm_target_btf() : NULL;

        if (needs != 0 && tb == NULL) {
            fprintf(stderr, "ls_vm: refusing --- this program carries CO-RE "
                            "relocation records%s but this binary has no `.BTF` to "
                            "resolve them against. Resolve the field offsets at "
                            "sign time (the offsets must match this build) or load "
                            "a binary that embeds its own type information.\n",
                    needs < 0 ? " (or could not be parsed, which is treated the same)"
                              : "");
            goto fail;
        }

        unsigned nrel = 0;
        int rrc = (needs != 0)
                ? ls_core_relocate((void *)elf, (uint32_t)elf_len, tb, &nrel)
                : LS_RELO_OK;
        if (rrc != LS_RELO_OK && rrc != -LS_RELO_ENOBTF) {
            fprintf(stderr, "ls_vm: refusing --- CO-RE relocation failed (rc=%d)\n", rrc);
            goto fail;
        }
        if (needs == 0 && g_cfg.verbose)
            fprintf(stderr, "ls_vm: no CO-RE records --- offsets are baked; the "
                            "binary's own type information was not read\n");
        if (g_cfg.verbose && nrel)
            fprintf(stderr, "ls_vm: CO-RE relocated %u field offset(s)\n", nrel);
    }

    /* Interpreter by default. The JIT is reachable by env var so its cost can be
     * MEASURED without a rebuild --- not because it is safe to run (O6: fuel has
     * no effect once JIT'd; O7: the prologue opens a 4KB frame with no probe). */
    /* uBPF selects by FUNCTION SYMBOL here, not section --- see O14 and the
     * check above, which is what makes passing `function` safe. */
    if (ubpf_load_elf_ex(vm, elf, elf_len, function, &err) < 0)
        goto fail;
    if (g_ls_config.load_error) {
        fprintf(stderr, "ls_vm: refusing --- invalid configuration map declaration\n");
        goto fail;
    }

    /* Fuel. Works in the interpreter; documented as having no effect once
     * compiled to native code, which is the other half of why this is the
     * interpreter path first. */
    ubpf_set_instruction_limit(vm, g_cfg.fuel ? g_cfg.fuel : 10000, NULL);

    if (g_cfg.jit) {
        char *jerr = NULL;
        /* ubpf_exec/_ex ALWAYS interpret --- they never dispatch to compiled
         * code. A JIT'd program is reached only through the function pointer
         * ubpf_compile returns, so storing it is what makes the JIT do anything
         * at all. Compiling and then calling ubpf_exec, as an earlier version of
         * this file did, JITs the program and throws the result away: the
         * measurement showed jit=1 and jit=0 within noise of each other, which
         * was the tell. */
        /* EXTENDED mode, not basic. Basic mode's generated prologue allocates
         * its own stack --- ubpf.h: "automatically allocates a stack" --- which
         * is the unprobed 4 KB frame finding O7 is about. Extended mode takes the
         * stack as an argument, so the same per-instance buffer serves both the
         * interpreter and the compiled path. */
        ubpf_set_jit_code_size(vm, LS_JIT_CODE_MAX);
        g_slots[slot].jit_fn = (void *)ubpf_compile_ex(vm, &jerr, ExtendedJitMode);
        if (g_slots[slot].jit_fn == NULL) {
            fprintf(stderr, "ls_vm: JIT requested but failed: %s\n", jerr ? jerr : "?");
            free(jerr);
            goto fail;
        }
    }

    g_slots[slot].vm    = vm;
    g_slots[slot].mode  = m;
    /* THE BUILDER COMES FROM THE DECLARED HOOK, not from the slot number. `section` is
     * "fentry/<hook>" and ls_symbol_is_in_section just checked that identity against the
     * program's own symbol, so it is the strongest statement available about what this
     * program expects to be handed. NULL --- no registered builder --- means the generic
     * five registers and no dereference. ls_slots.h records what went wrong when the slot
     * number decided this. */
    g_slots[slot].armed = true;

    if (g_cfg.verbose)
        fprintf(stderr, "ls_vm: ARMED slot=%d section=%s function=%s mode=%d"
                        " bytes=%lu origin=%s jit=%d\n",
                slot, section, function, (int)m, (unsigned long)elf_len,
                g_origin[0] ? g_origin : "builtin", (int)g_cfg.jit);

    if (g_cfg.bench)
        ls_vm_bench(slot, g_cfg.bench);

    if (g_cfg.selftest)
        ls_vm_selftest(slot, g_cfg.selftest);

    return slot;

fail:
    if (err) { fprintf(stderr, "ls_vm: arm failed: %s\n", err); free(err); }
    ubpf_destroy(vm);
    return -1;
}

/*
 * Reproduce the CVE condition against the armed shield --- LS_VM_SELFTEST.
 *
 * WHAT THIS DEMONSTRATES: the real verified program, in the real VM, inside the
 * real TMM binary, deciding on the exact input the vulnerable call site would
 * hand it --- a NULL protocol-transfer log profile. And, at level 2, that the
 * dereference which follows a FALLTHROUGH verdict really is fatal.
 *
 * WHAT IT DOES NOT DEMONSTRATE, and must not be reported as: that the hook is
 * correctly placed in http_psm_profile_name_lookup, or that live traffic reaches
 * it. Those are separate claims needing a configured listener and a security log
 * profile whose format string contains ${profile_name}. This synthesises the
 * condition; it does not drive the path.
 *
 * Deliberately not built from fake TMM structures. Walking
 * log_data->scb->uf -> connflow -> listener would mean synthesising four internal
 * types, and a crash inside flow_get_listener() would prove nothing about this
 * bug. The ctx is what the shield actually sees, so the ctx is what is reproduced.
 *
 *   LS_VM_SELFTEST=1  evaluate and report. Never crashes.
 *   LS_VM_SELFTEST=2  evaluate, and on FALLTHROUGH perform the real dereference.
 *                     With the shield armed this survives; with LS_SHIELD_ENABLE=0
 *                     it is a segfault. That difference is the whole demonstration.
 */
static void
ls_vm_selftest(int slot, unsigned level)
{
    /* The generic five-register context, exactly what the trampoline now hands every
     * program: arg[0] is the first argument register. There are no typed ctx builders any
     * more --- a CO-RE program reads the fields it needs by relocation, so the self-test's
     * job is only to feed the mechanism the CVE condition (a null source pointer) and see
     * whether the loaded program returns SAFE_RETURN. */
    struct ls_ctx_generic c;
    memset(&c, 0, sizeof c);          /* arg[0] == NULL --- the CVE condition (source pointer null) */

    enum ls_verdict v = ls_vm_call(slot, &c, sizeof c);

    fprintf(stderr,
            "ls_vm: SELFTEST cve-condition ptlp=NULL -> verdict=%s  (%s)\n",
            v == LS_SAFE_RETURN ? "SAFE_RETURN" : "FALLTHROUGH",
            v == LS_SAFE_RETURN
              ? "the shield would skip the body --- no dereference, no crash"
              : "the body would run --- the NULL dereference happens next");

    if (level < 2)
        return;

    if (v == LS_SAFE_RETURN) {
        fprintf(stderr, "ls_vm: SELFTEST survived --- shield prevented the "
                        "dereference. Re-run with LS_SHIELD_ENABLE=0 to see the "
                        "same binary crash.\n");
        return;
    }

    /* No shield, or it declined. Do what the vulnerable line does. */
    fprintf(stderr, "ls_vm: SELFTEST performing the unshielded dereference --- "
                    "this is expected to be fatal\n");
    fflush(stderr);
    {
        volatile const char *const *pp = (volatile const char *const *)(uintptr_t)c.arg[0];
        volatile char sink = *(*pp);      /* the source pointer, with arg[0] == NULL */
        (void)sink;
    }
    fprintf(stderr, "ls_vm: SELFTEST did NOT crash --- unexpected; the platform "
                    "may be mapping page zero\n");
}

int
ls_vm_arm_configured(const void *blob, size_t blob_len,
                     const char *section, const char *function)
{
    const void *prog = blob;
    size_t      len  = blob_len;

    if (!g_ready)
        return -1;

    /* The compiled-in blob is OPT-IN. A hardcoded, auto-armed shield is exactly what
     * the socket load path exists to remove, so unless the operator explicitly asked
     * for the built-in (LS_SHIELD_BUILTIN=1) or named a program to run in its place
     * (LS_SHIELD_PATH / LS_SHIELD_SECTION), arm nothing here and let the socket loader
     * be the only way a program arrives. */
    if (!g_cfg.builtin && !g_cfg.path && !g_cfg.section) {
        if (g_cfg.verbose)
            fprintf(stderr, "ls_vm: no built-in shield armed (LS_SHIELD_BUILTIN=0) --- "
                            "socket load is the only arming path\n");
        return -1;
    }

    /* A program on disk replaces the compiled-in one. Refusing on a bad path
     * rather than silently falling back to the built-in matters: an operator who
     * pointed at a file and got the old shield, with no error, would have no way
     * to tell which program is running. */
    if (g_cfg.path) {
        size_t n = ls_read_program(g_cfg.path);
        if (n == 0) {
            fprintf(stderr, "ls_vm: LS_SHIELD_PATH=%s unreadable or empty --- "
                            "refusing (NOT falling back to the built-in)\n", g_cfg.path);
            return -1;
        }
        prog = g_filebuf;
        len  = n;
        /* uBPF copies the program during load, so this buffer is dead after
         * ls_vm_arm returns --- freed below rather than held for the process
         * lifetime. */
        snprintf(g_origin, sizeof g_origin, "file:%s(%lu)", g_cfg.path, (unsigned long)n);
    } else {
        snprintf(g_origin, sizeof g_origin, "builtin(%lu)", (unsigned long)len);
    }

    int slot = ls_vm_arm(prog, len,
                         g_cfg.section  ? g_cfg.section  : section,
                         g_cfg.function ? g_cfg.function : function,
                         (enum ls_mode)g_cfg.mode);
    free(g_filebuf);
    g_filebuf = NULL;
    return slot;
}

/*
 * The ctx builder a slot's program declared, or NULL for "generic, dereference nothing".
 *
 * NULL for an out-of-range slot, an unarmed one, and an unregistered hook alike --- all three
 * mean the same thing to the caller, which is why one return value covers them.
 *
 * Acquire-loaded to pair with the release in ls_vm_reload: a core already inside the
 * trampoline must not see the new builder with the old program or the reverse.
 */
/*
 * Is signature enforcement on?
 *
 * An accessor rather than exporting g_cfg, and rather than letting ls_vm_load.c read the
 * environment itself. One place parses configuration; two would eventually disagree, and the one
 * place they must not disagree is whether a security gate is armed.
 */
int
ls_vm_sig_enforce(void)
{
    return g_cfg.sig_enforce ? 1 : 0;
}




static enum ls_verdict
ls_vm_run(int slot, void *ctx, size_t ctx_len,
          const struct ls_snapshot_id *identity, int *completed)
{
    uint64_t ret = 0;

    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return LS_FALLTHROUGH;

    if (ls_map_enter() != 0)
        return LS_FALLTHROUGH;
    struct ls_slot *s = &g_slots[slot];

    /* Both of these can be replaced under us by the loader thread, so read each
     * exactly once. Reading s->vm twice could straddle a swap and use one
     * program's VM with another's expectations. */
    enum ls_mode mode = __atomic_load_n(&s->mode, __ATOMIC_ACQUIRE);
    void *vm = __atomic_load_n(&s->vm, __ATOMIC_ACQUIRE);
    if (!s->armed || vm == NULL || mode == LS_MODE_DISABLE) {
        ls_map_leave();
        return LS_FALLTHROUGH;
    }
    if ((identity == NULL && s->is_snapshot) ||
        (identity != NULL &&
         (!s->is_snapshot || !identity->instance ||
          identity->epoch == UINT64_MAX ||
          identity->instance != s->snapshot_id.instance ||
          identity->epoch != __atomic_load_n(&s->snapshot_id.epoch,
                                             __ATOMIC_ACQUIRE)))) {
        ls_map_leave();
        return LS_FALLTHROUGH;
    }

    /* PUBLISH WHICH SLOT IS RUNNING, for helpers that need it and cannot be told.
     * uBPF's external_function_t has no context parameter, so bpf_ringbuf_output has no
     * way to know which slot invoked it; a thread-local is correct because TMM is
     * core-pinned and run-to-completion, so exactly one program runs on this thread at
     * any instant. Set AFTER the early returns so a disabled or unarmed slot never
     * leaves a stale value behind, and cleared on every exit path below. */
    g_ls_cur_slot = slot;
    ls_config_begin(&g_ls_config_view, (unsigned)slot);

    /* A non-zero return from ubpf_exec is an execution fault --- fuel exhausted,
     * or a bounds check the interpreter enforces at run time. Fall through: a
     * shield that cannot run must not take the flow with it. Counted, because a
     * silent fail-open is indistinguishable from a shield that never matched. */
    uint64_t t0 = g_cfg.timing ? ls_cycles() : 0;
    /* Compiled path if we have one, interpreter otherwise. Both take the stack
     * from us: ubpf_exec would allocate and touch 4 KB of C stack on every packet
     * reaching this hook, and basic-mode JIT code would do the same in its
     * prologue without a guard-page probe (O7). */
    int rc = 0;
    void *jf = __atomic_load_n(&s->jit_fn, __ATOMIC_ACQUIRE);
    if (jf != NULL) {
        ret = ((ubpf_jit_ex_fn)jf)(ctx, ctx_len, g_prog_stack, LS_PROG_STACK_SIZE);
    } else {
        rc = ubpf_exec_ex(vm, ctx, ctx_len, &ret, g_prog_stack, LS_PROG_STACK_SIZE);
    }
    g_ls_config_view.active = 0;
    g_ls_cur_slot = -1;
    ls_map_leave();
    if (g_cfg.timing) {
        uint64_t d = ls_cycles() - t0;
        s->cycles += d;
        if (d > s->cycles_max) s->cycles_max = d;
        if (s->cycles_min == 0 || d < s->cycles_min) s->cycles_min = d;
    }
    if (rc != 0) {
        s->errors++;
        return LS_FALLTHROUGH;
    }
    if (completed != NULL)
        *completed = 1;

    /* Sample the ctx. A fixed-size memcpy into a slot-resident ring: no
     * allocation, no lock, no syscall. Gated so the shipped path is untouched
     * unless asked --- same discipline as timing. */
    if (g_cfg.samples) {
        struct ls_ctx_sample *sm = &s->samples[s->sample_next % LS_CTX_SAMPLES];
        size_t n = ctx_len < LS_CTX_SAMPLE_BYTES ? ctx_len : LS_CTX_SAMPLE_BYTES;
        sm->seq = s->fired;
        sm->len = (uint32_t)ctx_len;
        sm->verdict = (uint32_t)ret;
        memcpy(sm->bytes, ctx, n);
        s->sample_next++;
    }

    if (s->fired == 0 && g_cfg.verbose)
        fprintf(stderr, "ls_vm: FIRST INVOCATION slot=%d --- the hook is reached\n", slot);
    s->fired++;
    if (g_cfg.report_every && (s->fired % g_cfg.report_every) == 0)
        ls_vm_report();

    if (identity != NULL || ret != LS_SAFE_RETURN)
        return LS_FALLTHROUGH;

    s->safe_returns++;

    /* THE EVIDENCE EVENT. A counter answers "how many"; this answers "show me the
     * one it stopped". Emitted in BOTH modes --- enforce (blocked) and monitor
     * (WOULD have blocked) --- so a shield validated in monitor still produces the
     * record a reviewer needs, tagged with which mode it was. Rate-limited and
     * ring-gated inside ls_tp_emit_shield; a no-op on the shipped default. Off the
     * common path: SAFE_RETURN fires only when the exploit precondition holds. */
    ls_tp_emit_shield(slot, s->gen, (unsigned)mode, (unsigned)ret, ctx, ctx_len);

    /* Monitor mode counts the selection and applies nothing. The counters above
     * are what make a monitor-mode hit distinguishable from a miss. */
    return (mode == LS_MODE_ENFORCE) ? LS_SAFE_RETURN : LS_FALLTHROUGH;
}

enum ls_verdict
ls_vm_call(int slot, void *ctx, size_t ctx_len)
{
    return ls_vm_run(slot, ctx, ctx_len, NULL, NULL);
}

int
ls_vm_snapshot_identity(int slot, struct ls_snapshot_id *identity)
{
    int snapshot = 0;
    memset(identity, 0, sizeof *identity);
    if (slot >= 0 && slot < LS_MAX_SLOTS && g_slots[slot].is_snapshot) {
        identity->instance = g_slots[slot].snapshot_id.instance;
        identity->epoch = __atomic_load_n(&g_slots[slot].snapshot_id.epoch,
                                          __ATOMIC_ACQUIRE);
        snapshot = 1;
    }
    return snapshot;
}

int
ls_vm_snapshot_call(int slot, const struct ls_snapshot_id *identity,
                    struct ls_snapshot_ctx *ctx)
{
    int completed = 0;
    uint32_t phase = ctx->phase;
    if (identity != NULL)
        (void)ls_vm_run(slot, ctx, sizeof *ctx, identity, &completed);
    if (!completed && slot >= 0 && slot < LS_MAX_SLOTS) {
        if (phase == LS_SNAPSHOT_ENTRY)
            g_slots[slot].snapshot_entry_errors++;
        else
            g_slots[slot].snapshot_return_errors++;
    }
    return completed ? 0 : -1;
}

/*
 * Publish a new program over a live slot. The whole point of this function is
 * the ORDER: everything expensive and everything fallible happens first, into
 * storage the data path cannot see, and the data path only ever observes a
 * single pointer store that is either the old program or the new one.
 *
 * What this is NOT: the ordered cross-core publish of item 0. A call already in
 * flight keeps the VM it loaded at entry; the next call gets the new one. That
 * is atomic-per-call replacement, which is sufficient for one hook and one
 * program and is not sufficient for a coordinated multi-hook update.
 *
 * The old VM is deliberately LEAKED. Freeing it needs proof that no core is
 * still inside it --- items 0b/0c --- and a wrong free here is a use-after-free
 * on the data path. Leaking is bounded by the number of loads and cannot
 * corrupt anything; a load loop would exhaust memory, which is a real limit
 * stated rather than hidden.
 */
int
ls_vm_reload(int slot, const void *elf, size_t elf_len,
             const char *section, const char *function, enum ls_mode m)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS || !g_ready)
        return -1;

    /* Prepare into a spare slot: create, identity-check, load, JIT if asked.
     * All of it off the data path, all of it able to fail harmlessly. */
    int staged = ls_vm_arm(elf, elf_len, section, function, m);
    if (staged < 0)
        return -1;
    if (staged == slot)
        return slot;                      /* nothing was live here */

    struct ls_slot *live = &g_slots[slot];
    struct ls_slot *new  = &g_slots[staged];

    /* The publish. Release-ordered so each object's contents are visible to any
     * core that observes the pointer.
     *
     * jit_fn MUST be published with vm, and this is not a detail. ls_vm_call
     * prefers jit_fn whenever it is non-NULL and only falls back to the
     * interpreter when it is NULL --- so a swap that replaced vm alone left the
     * PREVIOUS program's compiled code executing while the new program sat in an
     * interpreter nothing ever consulted. Every load over the socket appeared to
     * succeed, the counters moved, and the resident program kept answering. The
     * two observable symptoms were a verdict that ignored the loaded program and
     * a slot whose behaviour never changed no matter what was sent to it.
     *
     * Order matters for a core already inside ls_vm_call:
     *   1. mode  -> DISABLE   readers take the early-out and fall through
     *   2. jit_fn-> NULL      no reader can enter the OLD compiled code
     *   3. vm    -> new       the interpreter now backs this slot
     *   4. jit_fn-> new       compiled path returns, matching the new vm
     *   5. mode  -> m         the slot goes live again
     * Steps 2-4 are what make (vm, jit_fn) observably one program rather than
     * two. A reader that sampled the old jit_fn before step 2 runs old compiled
     * code to completion, which is safe only because the old VM is leaked rather
     * than destroyed --- the code it points at stays mapped. That known debt
     * (item 0c) is load-bearing here; reclaiming it needs the quiescence pass,
     * not a free() in this function. */
    __atomic_store_n(&live->mode, LS_MODE_DISABLE, __ATOMIC_RELAXED);
    __atomic_store_n(&live->jit_fn, NULL, __ATOMIC_RELEASE);
    __atomic_store_n(&live->vm, new->vm, __ATOMIC_RELEASE);   /* old VM leaked */
    __atomic_store_n(&live->jit_fn, new->jit_fn, __ATOMIC_RELEASE);
    live->armed = true;
    live->is_exit = new->is_exit;   /* the kind rides with the program on the swap */
    live->is_snapshot = new->is_snapshot;
    live->snapshot_id = new->snapshot_id;
    __atomic_store_n(&live->mode, m, __ATOMIC_RELEASE);
    live->safe_value = new->safe_value; /* and its safe-return value (item 7) */
    live->gen++;              /* so STATUS can distinguish residue from result */

    new->armed = false;                   /* the staging slot goes back */
    new->vm = NULL;
    new->jit_fn = NULL;

    fprintf(stderr, "ls_vm: RELOADED slot=%d mode=%d bytes=%lu "
                    "(previous VM leaked --- reclamation is item 0c)\n",
            slot, (int)m, (unsigned long)elf_len);
    return slot;
}

void
ls_vm_set_mode(int slot, enum ls_mode m)
{
    if (slot < 0 || slot >= LS_MAX_SLOTS)
        return;
    if (g_slots[slot].is_snapshot) {
        if (m > LS_MODE_MONITOR)
            m = LS_MODE_DISABLE;
        uint64_t epoch = __atomic_load_n(&g_slots[slot].snapshot_id.epoch,
                                         __ATOMIC_RELAXED);
        if (epoch != UINT64_MAX)
            __atomic_store_n(&g_slots[slot].snapshot_id.epoch, epoch + 1,
                             __ATOMIC_RELEASE);
    }
    __atomic_store_n(&g_slots[slot].mode, m, __ATOMIC_RELEASE);
    fprintf(stderr, "ls_vm: slot=%d mode -> %d\n", slot, (int)m);
}

void
ls_vm_fini(void)
{
    ls_vm_report();
    for (int i = 0; i < LS_MAX_SLOTS; i++) {
        if (g_slots[i].armed) {
            ubpf_destroy(g_slots[i].vm);
            g_slots[i].armed = false;
        }
    }
    g_ready = false;
}

