#include "../config_snapshot.bpf.h"
#include "operation_target_abi.h"
struct ot_ctx { jm_u64 arg[5], result, reserved[6]; };
struct ot_state { jm_u64 instance, calls, failures, reserved; };
struct ot_policy { jm_u64 run, reserved[3]; };
