            return -1;
        if ((jm_u32)t->start < minimum || (jm_u32)t->end > end)
            return -1;
        minimum = t->end;
        if (match)
            return index;
        if ((jm_u32)(i + 1) < count &&
                (t->sibling <= (int)index || (jm_u32)t->sibling >= v->used))
            return -1;
        index = t->sibling;
