        if (e->status == OT_NO_TARGET)
            e->status = TM_NO_LITERAL_METHOD;
        return;
    }
    e->status = OT_UNSUPPORTED_METHOD;
    if (s.t.type != 3)
        return;
    jm_u32 n = s.t.end - s.t.start;
    if (n != 10 && n != 14)
        return;
    if (bytes(e, v.head, s.t.start, n))
        return;
