        e->getter_result = OT_TOOL;
    if (n == 14 && !__builtin_memcmp(e->value, "resources/read", 14))
        e->getter_result = OT_RESOURCE;
    __builtin_memset(e->value, 0, sizeof e->value);
    if (!e->getter_result)
