                &s.t) < 0)
        return;
    if (s.t.type != 3) {
        e->status = TM_NONSTRING;
        return;
    }
    e->original_length = s.t.end - s.t.start;
    n = e->original_length;
    if (n > 64)
        n = 64;
    if (bytes(e, v.head, s.t.start, n))
        return;
    e->copied_length = n;
    e->status = n < e->original_length ? JM_TRUNCATED : JM_COMPLETE;
}

